use crate::aap::caps::state_read;

struct Node;

/// Parse a stored subscription value. Accepts a JSON array of strings,
/// or newline/comma-separated URLs. Blank entries and `#` comments are dropped,
/// as are duplicates (first occurrence wins).
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let mut out: Vec<String> = Vec::new();

    let mut push = |s: String| {
        let s = s.trim().to_string();
        if !s.is_empty() && !s.starts_with('#') && !out.contains(&s) {
            out.push(s);
        }
    };

    if trimmed.starts_with('[') {
        // Minimal JSON string-array reader.
        let mut chars = trimmed.chars().peekable();
        let mut in_str = false;
        let mut cur = String::new();
        while let Some(c) = chars.next() {
            if in_str {
                match c {
                    '\\' => {
                        if let Some(n) = chars.next() {
                            match n {
                                'n' => cur.push('\n'),
                                't' => cur.push('\t'),
                                'r' => cur.push('\r'),
                                '/' => cur.push('/'),
                                '\\' => cur.push('\\'),
                                '"' => cur.push('"'),
                                'u' => {
                                    let hex: String = chars.by_ref().take(4).collect();
                                    if let Some(ch) = u32::from_str_radix(&hex, 16)
                                        .ok()
                                        .and_then(char::from_u32)
                                    {
                                        cur.push(ch);
                                    }
                                }
                                other => cur.push(other),
                            }
                        }
                    }
                    '"' => {
                        in_str = false;
                        push(core::mem::take(&mut cur));
                    }
                    other => cur.push(other),
                }
            } else if c == '"' {
                in_str = true;
            }
        }
    } else {
        for part in trimmed.split(|c| c == '\n' || c == ',') {
            push(part.to_string());
        }
    }

    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls = Vec::new();
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

export!(Node);
